function validate([logs]) {
  if (!Array.isArray(logs) || logs.length < 1 || logs.length > 100) return 'logs needs 1 to 100 entries.';
  for (const log of logs) {
    if (typeof log !== 'string' || log.length < 3 || log.length > 100) return 'Each log has 3 to 100 characters.';
    const parts = log.split(' ');
    if (parts.length < 2 || parts.some(p => p === '')) return 'Separate words with single spaces; each log needs an identifier and a word.';
    if (!/^[a-z0-9]+$/.test(parts[0])) return 'Identifiers use lowercase letters and digits.';
    const rest = parts.slice(1);
    if (!rest.every(p => /^[a-z]+$/.test(p)) && !rest.every(p => /^[0-9]+$/.test(p))) return 'Words after the identifier must be all letters or all digits.';
  }
  return null;
}

