function reorderLogFiles(logs) {
  const letterLogs = [];
  const digitLogs = [];

  for (const log of logs) {
    const space = log.indexOf(' ');
    const id = log.slice(0, space);
    const content = log.slice(space + 1);
    const isDigit = content[0] >= '0' && content[0] <= '9';
    if (isDigit) {
      digitLogs.push(log);
    } else {
      letterLogs.push({ id, content, log });
    }
  }

  letterLogs.sort((a, b) => {
    if (a.content !== b.content) {
      return a.content < b.content ? -1 : 1;
    }
    if (a.id !== b.id) {
      return a.id < b.id ? -1 : 1;
    }
    return 0;
  });

  const sorted = letterLogs.map(entry => entry.log);
  return sorted.concat(digitLogs);
}

