function reorderLogFiles(logs) {
  const words = (log) => log.split(' ');
  const isLetterLog = (log) => /^[a-z]+$/.test(words(log)[1]);
  const letters = logs.filter(isLetterLog);
  const digits = logs.filter(log => !isLetterLog(log));
  const before = (x, y) => {
    const [ix, ...cx] = words(x), [iy, ...cy] = words(y);
    const kx = cx.join(' '), ky = cy.join(' ');
    return kx < ky || (kx === ky && ix < iy);
  };
  for (let a = 0; a < letters.length; a++)
    for (let b = a + 1; b < letters.length; b++)
      if (before(letters[b], letters[a])) [letters[a], letters[b]] = [letters[b], letters[a]];
  return [...letters, ...digits];
}

