function generate(rand, size) {
  const large = size === 'large';
  const int = (k) => Math.floor(rand() * k);
  const lettersPool = large ? 'abcdefghijklmnopqrstuvwxyz' : 'abz';
  const alnum = 'abcdefghijklmnopqrstuvwxyz0123456789';
  const word = (chars, maxLen) => Array.from({ length: 1 + int(maxLen) }, () => chars[int(chars.length)]).join('');
  const smallIds = ['a1', 'b', '0', 'x9', 'let1', '10'];
  const n = large ? 100 : 1 + int(7);
  const logs = [];
  for (let k = 0; k < n; k++) {
    const id = large ? word(alnum, 4) : smallIds[int(smallIds.length)];
    const digit = rand() < 0.4;
    const count = 1 + int(large ? 6 : 3);
    const parts = [];
    for (let w = 0; w < count; w++) parts.push(digit ? word('0123456789', large ? 6 : 2) : word(lettersPool, large ? 6 : 2));
    let log = id + ' ' + parts.join(' ');
    if (log.length > 100) log = id + ' ' + parts[0];
    if (log.length < 3) log += digit ? '7' : 'a';
    logs.push(log);
  }
  // Repeat some contents so that ties broken by identifier appear.
  if (large) for (let k = 0; k < 15; k++) {
    const from = logs[int(n)], at = int(n);
    logs[at] = word(alnum, 4) + from.slice(from.indexOf(' '));
  }
  return [logs];
}
